import{_ as t,l as i,o as e,c as n,v as l,p as s,x as r,d as A,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"LoRA 合并与冲突","description":"","frontmatter":{"title":"LoRA 合并与冲突","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lora-merge-conflict.md","filePath":"llm/lora-merge-conflict.md","lastUpdated":1789023840000}'),p={name:"llm/lora-merge-conflict.md"};function _(E,a,h,c,u,B){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="lora-合并与冲突" tabindex="-1">LoRA 合并与冲突 <a class="header-anchor" href="#lora-合并与冲突" aria-label="Permalink to &quot;LoRA 合并与冲突&quot;">​</a></h1><div class="epigraph"><p>两个适配器相加，秩至多相加，任务方向却可能互相抵消；线性合并是产品操作，不是 LoRA 原论文保证的交换律。</p><footer>—— 承接 Hu 等 LoRA（2021）的单任务合并；冲突侧对照 Yadav 等 TIES-Merging（NeurIPS 2023）、Yu 等 DARE（ICML 2024）</footer></div><p><a href="/llm/p-tuning-v2">P-tuning v2</a> 用切换前缀避免把任务写进 \\(W\\)。LoRA 服务常走另一条：把 \\(\\Delta W_i=B_iA_i\\) 加进同一份 \\(W_0\\)，希望同时会编程又会客服。<a href="/llm/lora">LoRA 课</a>已警告多适配器相加无通用保证。本课把缺口展开：何时加法近似成立、符号冲突怎么消、以及为何<a href="/llm/rslora">rsLoRA</a> 缩放不同的适配器不能裸加。下一课再谈 MoE 上插在哪里。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单任务部署：算 \\(W=W_0+\\gamma BA\\)，推理与稠密相同。多任务想免去切换 GEMM，就写</p> \\[W=W_0+\\sum_i \\lambda_i\\gamma_i B_iA_i. \\]<p>若各 \\(\\Delta W_i\\) 作用在近似正交的子空间、且 \\(\\lambda_i\\) 小，表现像「技能并集」。若两个任务改同一批通道而符号相反（一个要更冗长、一个要更短），加法变成抵消或随机胜出。TIES-Merging（Yadav 等人，NeurIPS 2023）指出模型合并里的三类干扰：符号不一致、小幅度噪声、密度过高。LoRA 合并是模型合并的低秩特例。</p><p>不同 \\(r\\)、不同 \\(\\gamma\\)（含 rsLoRA 与否）、不同插入位置，连矩阵形状都不共享，不能逐元素加。</p><h3 id="合并不可逆-除非另存因子" tabindex="-1">合并不可逆，除非另存因子 <a class="header-anchor" href="#合并不可逆-除非另存因子" aria-label="Permalink to &quot;合并不可逆，除非另存因子&quot;">​</a></h3><p>加进 \\(W_0\\) 后丢掉 \\(A,B\\)，无法拆回任务。要可逆，必须保存因子或保存合并前的 \\(W_0\\)。ReLoRA 训练期合并与此处产品合并是同一加法，目的相反：前者堆秩，后者堆任务。</p><p><span class="marginnote">Huang 等人的 LoRAHub 用少量样本学组合系数 \\(\\lambda_i\\)。系数可学，说明裸 \\(\\lambda_i=1\\) 通常不是最优。DARE（Yu 等，ICML 2024）则先随机丢差分再缩放，减轻同源模型合并的干扰。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先对齐：同一基座检查点、同一插入模块集合、同一<a href="/llm/chat-template">模板</a>。然后选策略：（1）不合并，运行时切适配器；（2）加权和，扫 \\(\\lambda\\)；（3）TIES 式：修剪小幅度、对冲突符号选举、再平均；（4）在验证集上学 \\(\\lambda\\)（LoRAHub 类）。评测必须含单任务回归：合并后任务 A 不得默默掉到不可用。</p><p>缩放：先把每个适配器的 \\(\\gamma BA\\) 物化到同一表示再加。一个用 \\(\\alpha/r\\)、一个用 \\(\\alpha/\\sqrt{r}\\)，直接加 \\(B,A\\) 是 bug。</p>',14)),(e(),s(m,null,{default:r(()=>[d(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A1%5B%22%E9%80%82%E9%85%8D%E5%99%A8%20A%22%5D%20--%3E%20C%5B%22%E5%AF%B9%E9%BD%90%E5%9F%BA%E5%BA%A7%E4%B8%8E%20%CE%B3%22%5D%0A%20%20A2%5B%22%E9%80%82%E9%85%8D%E5%99%A8%20B%22%5D%20--%3E%20C%0A%20%20C%20--%3E%20M%5B%22%E5%8A%A0%E6%9D%83%20%2F%20TIES%20%2F%20%E5%AD%A6%20%CE%BB%22%5D%0A%20%20M%20--%3E%20V%5B%22%E5%8D%95%E4%BB%BB%E5%8A%A1%20%2B%20%E8%81%94%E5%90%88%E9%AA%8C%E8%AF%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>数据侧：两个 LoRA 若 SFT 谱系不同（FLAN 对 ShareGPT），合并等于混条件分布，<a href="/llm/response-only-loss">仅回复</a>学到的结束符习惯会打架。优先在数据配比上混训一个适配器，而不是训两个再加。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(\\Delta W_1+\\Delta W_2\\) 的列空间是两者列空间的和，秩 \\(\\le r_1+r_2\\)。干扰发生在重叠的奇异方向上：同向则加强（可能过饱和），反向则相消。TIES 的符号选举假设「多数任务同意的符号是真信号」——对同源、同目标的检查点较真，对「安全 LoRA + 越狱 LoRA」荒谬。DARE 假设差分里有大量冗余：随机丢弃仍能保留能力，再放大补偿。LoRA 很稀疏时 DARE 可能把仅有的 \\(r\\) 个方向丢掉。</p><p>服务期不合并、只切 \\(A,B\\)，没有加法冲突，但有加载延迟与额外 GEMM。Punica 一类内核优化的是切适配器，不是让加法变合法。</p><p><span class="marginnote">BitFit 的 Δb 相加同样会冲突，只是诊断更容易：看通道符号。前缀 KV 应切换，平均前缀常得到无意义的键。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>没有通用的「把商店里的 LoRA 线性融合」。安全与能力适配器尤其不要裸加。同一数据不同随机种子的soup（模型汤）比异质任务相加更安全。合并后要做源域回归：加法可能意外放大遗忘。MoE 上还有专家路由与 LoRA 的位置冲突，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单任务合并 \\(W_0+\\gamma BA\\) 是合法部署；多任务求和无交换律保证。</li><li>先对齐基座、插入位置与缩放，再谈 \\(\\lambda\\) 或 TIES。</li><li>符号冲突会相消；异质谱系优先混训而不是事后加。</li><li>可逆性要求保留因子或原 \\(W_0\\)。</li><li>运行时切换回避加法，付出额外 GEMM。</li><li>出处：Hu 等，LoRA，2021；Yadav 等，TIES-Merging，NeurIPS 2023；Yu 等，DARE，ICML 2024。</li></ul>',9))])}const b=t(p,[["render",_]]);export{R as __pageData,b as default};
